1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Tetris</title>
7	<style>
8	  :root {
9	    --bg: #111418;
10	    --panel: #1b2027;
11	    --grid: #232a33;
12	    --text: #e8ecf1;
13	    --muted: #8b96a5;
14	    --I: #22c7e8;
15	    --O: #f2c613;
16	    --T: #a64ee0;
17	    --S: #3fc15a;
18	    --Z: #e8453c;
19	    --J: #3a6fe8;
20	    --L: #f08a24;
21	  }
22	  * { box-sizing: border-box; }
23	  body {
24	    margin: 0;
25	    min-height: 100vh;
26	    background: var(--bg);
27	    color: var(--text);
28	    font: 15px/1.4 system-ui, -apple-system, "Segoe UI", sans-serif;
29	    display: flex;
30	    align-items: center;
31	    justify-content: center;
32	    padding: 16px;
33	  }
34	  .game { display: flex; gap: 20px; align-items: flex-start; flex-wrap: wrap; justify-content: center; }
35	  .board {
36	    display: grid;
37	    grid-template-columns: repeat(10, 28px);
38	    grid-template-rows: repeat(20, 28px);
39	    gap: 1px;
40	    background: var(--grid);
41	    border: 2px solid var(--grid);
42	    border-radius: 4px;
43	  }
44	  .cell { background: var(--bg); }
45	  .side { display: flex; flex-direction: column; gap: 12px; min-width: 140px; }
46	  .box { background: var(--panel); border-radius: 6px; padding: 10px 12px; }
47	  .label { color: var(--muted); font-size: 12px; text-transform: uppercase; letter-spacing: .08em; }
48	  .value { font-size: 22px; font-weight: 600; font-variant-numeric: tabular-nums; }
49	  .preview {
50	    display: grid;
51	    grid-template-columns: repeat(4, 20px);
52	    grid-template-rows: repeat(2, 20px);
53	    gap: 1px;
54	    margin-top: 6px;
55	  }
56	  .preview div { background: transparent; }
57	  .next-list { display: flex; flex-direction: column; gap: 8px; }
58	  .board-wrap { position: relative; }
59	  .game-over {
60	    position: absolute; inset: 0; display: flex; align-items: center; justify-content: center;
61	    background: rgba(17, 20, 24, .78); font-size: 24px; font-weight: 600; border-radius: 4px;
62	  }
63	  .p-I { background: var(--I) !important; }
64	  .p-O { background: var(--O) !important; }
65	  .p-T { background: var(--T) !important; }
66	  .p-S { background: var(--S) !important; }
67	  .p-Z { background: var(--Z) !important; }
68	  .p-J { background: var(--J) !important; }
69	  .p-L { background: var(--L) !important; }
70	  button {
71	    background: var(--panel); color: var(--text); border: 1px solid var(--grid);
72	    border-radius: 6px; padding: 8px 12px; font: inherit; cursor: pointer;
73	  }
74	  button:hover { border-color: var(--muted); }
75	  .keys { color: var(--muted); font-size: 13px; }
76	</style>
77	</head>
78	<body>
79	<div class="game">
80	  <div class="board-wrap">
81	    <div class="board" data-testid="board" id="board"></div>
82	    <div class="game-over" data-testid="game-over" id="game-over" hidden>Game over</div>
83	  </div>
84	  <div class="side">
85	    <div class="box"><div class="label">Score</div><div class="value" data-testid="score" id="score">0</div></div>
86	    <div class="box"><div class="label">Level</div><div class="value" data-testid="level" id="level">1</div></div>
87	    <div class="box"><div class="label">Lines</div><div class="value" data-testid="lines" id="lines">0</div></div>
88	    <div class="box"><div class="label">Next</div><div class="next-list" data-testid="next-piece" id="preview"></div></div>
89	    <button id="restart" type="button">New game</button>
90	    <div class="keys">← → move<br>↑ rotate<br>↓ soft drop<br>Space hard drop</div>
91	  </div>
92	</div>
93	<script>
94	(function () {
95	  "use strict";
96	
97	  var ROWS = 20, COLS = 10;
98	  var TYPES = ["I", "O", "T", "S", "Z", "J", "L"];
99	
100	  // Spawn shapes as [row, col] offsets from the piece origin.
101	  var SHAPES = {
102	    I: [[0, 0], [0, 1], [0, 2], [0, 3]],
103	    O: [[0, 1], [0, 2], [1, 1], [1, 2]],
104	    T: [[0, 1], [1, 0], [1, 1], [1, 2]],
105	    S: [[0, 1], [0, 2], [1, 0], [1, 1]],
106	    Z: [[0, 0], [0, 1], [1, 1], [1, 2]],
107	    J: [[0, 0], [1, 0], [1, 1], [1, 2]],
108	    L: [[0, 2], [1, 0], [1, 1], [1, 2]]
109	  };
110	  // Side length of the square each shape rotates within.
111	  var BOX = { I: 4, O: 2, T: 3, S: 3, Z: 3, J: 3, L: 3 };
112	  var SPAWN_COL = 3;
113	  var GRAVITY_MS = 1000;
114	  var PREVIEW_COUNT = 3;
115	
116	  // Locking rule (project decision): a gravity step that cannot move the piece
117	  // down counts one lock tick; the piece locks on the LOCK_TICKS-th tick.
118	  // Left/right while resting restarts the delay, at most MAX_LOCK_RESETS times
119	  // per piece. Soft drop on a resting piece restarts it too, from the same
120	  // per-piece allowance. Hard drop locks at once.
121	  var LOCK_TICKS = 2;
122	  var MAX_LOCK_RESETS = 3;
123	  // Rotation tries these sideways shifts, in order, until one fits.
124	  var KICKS = [0, -1, 1, -2, 2];
125	
126	  // Scoring rule (project decision): a clear scores CLEAR_POINTS[rows] x level.
127	  // Clearing rows together must always beat clearing them one at a time.
128	  // Soft drop scores 1 per cell moved by the player (gravity scores nothing);
129	  // hard drop scores 2 per cell dropped. Drop points are not multiplied.
130	  var CLEAR_POINTS = [0, 100, 300, 500, 800];
131	  var SOFT_DROP_POINTS = 1;
132	  var HARD_DROP_POINTS = 2;
133	
134	  var state = {
135	    board: [],      // ROWS x COLS, "" or piece letter
136	    current: null,  // { type, row, col, shape, lockTicks, lockResets }
137	    next: [],
138	    score: 0,
139	    level: 1,
140	    lines: 0,
141	    status: "running"
142	  };
143	
144	  // ---- core logic ----
145	
146	  function emptyBoard() {
147	    var b = [];
148	    for (var r = 0; r < ROWS; r++) {
149	      var row = [];
150	      for (var c = 0; c < COLS; c++) row.push("");
151	      b.push(row);
152	    }
153	    return b;
154	  }
155	
156	  function randomType() {
157	    return TYPES[Math.floor(Math.random() * TYPES.length)];
158	  }
159	
160	  function cellsOf(piece, dRow, dCol) {
161	    return piece.shape.map(function (o) {
162	      return [piece.row + (dRow || 0) + o[0], piece.col + (dCol || 0) + o[1]];
163	    });
164	  }
165	
166	  function fits(piece, dRow, dCol) {
167	    return cellsOf(piece, dRow, dCol).every(function (p) {
168	      return p[0] >= 0 && p[0] < ROWS && p[1] >= 0 && p[1] < COLS && state.board[p[0]][p[1]] === "";
169	    });
170	  }
171	
172	  function spawn() {
173	    var type = state.next.length ? state.next.shift() : randomType();
174	    while (state.next.length < PREVIEW_COUNT) state.next.push(randomType());
175	    var piece = { type: type, row: 0, col: SPAWN_COL, shape: SHAPES[type], lockTicks: 0, lockResets: 0 };
176	    // Game over: the new piece has nowhere to go. It is not placed.
177	    if (!fits(piece, 0, 0)) {
178	      state.current = null;
179	      state.status = "gameover";
180	      return;
181	    }
182	    state.current = piece;
183	  }
184	
185	  function lock() {
186	    var piece = state.current;
187	    cellsOf(piece).forEach(function (p) { state.board[p[0]][p[1]] = piece.type; });
188	    state.current = null;
189	    clearLines();
190	    spawn();
191	  }
192	
193	  // Remove every full row; rows above drop down. Scores the clear.
194	  function clearLines() {
195	    var kept = state.board.filter(function (row) {
196	      return row.some(function (t) { return t === ""; });
197	    });
198	    var cleared = ROWS - kept.length;
199	    if (!cleared) return;
200	    while (kept.length < ROWS) kept.unshift(emptyBoard()[0]);
201	    state.board = kept;
202	    state.lines += cleared;
203	    state.score += CLEAR_POINTS[cleared] * state.level;
204	  }
205	
206	  function tryMove(dRow, dCol) {
207	    if (!state.current || !fits(state.current, dRow, dCol)) return false;
208	    state.current.row += dRow;
209	    state.current.col += dCol;
210	    if (dRow > 0) state.current.lockTicks = 0;
211	    return true;
212	  }
213	
214	  // If the lock delay is running, restart it (capped per piece).
215	  function resetLockDelay(piece) {
216	    if (piece.lockTicks > 0 && piece.lockResets < MAX_LOCK_RESETS) {
217	      piece.lockResets++;
218	      piece.lockTicks = 0;
219	    }
220	  }
221	
222	  function shift(dCol) {
223	    var piece = state.current;
224	    if (!tryMove(0, dCol)) return;
225	    resetLockDelay(piece);
226	  }
227	
228	  function rotateCW() {
229	    var piece = state.current;
230	    if (!piece || piece.type === "O") return;
231	    var n = BOX[piece.type];
232	    var turned = {
233	      type: piece.type, row: piece.row, col: piece.col,
234	      shape: piece.shape.map(function (o) { return [o[1], n - 1 - o[0]]; })
235	    };
236	    for (var i = 0; i < KICKS.length; i++) {
237	      if (fits(turned, 0, KICKS[i])) {
238	        piece.shape = turned.shape;
239	        piece.col += KICKS[i];
240	        return;
241	      }
242	    }
243	  }
244	
245	  // One gravity step. The timer and __tetris.tick both call this.
246	  function gravityStep() {
247	    if (state.status !== "running" || !state.current) return;
248	    if (tryMove(1, 0)) return;
249	    state.current.lockTicks++;
250	    if (state.current.lockTicks >= LOCK_TICKS) lock();
251	  }
252	
253	  var actions = {
254	    left: function () { if (state.current) shift(-1); },
255	    right: function () { if (state.current) shift(1); },
256	    rotateCW: rotateCW,
257	    softDrop: function () {
258	      if (!state.current) return;
259	      if (tryMove(1, 0)) state.score += SOFT_DROP_POINTS;
260	      else resetLockDelay(state.current);
261	    },
262	    hardDrop: function () {
263	      if (!state.current) return;
264	      while (tryMove(1, 0)) state.score += HARD_DROP_POINTS;
265	      lock();
266	    }
267	  };
268	
269	  function doAction(name) {
270	    if (state.status !== "running" || !actions[name]) return;
271	    actions[name]();
272	    render();
273	  }
274	
275	  function newGame(queue) {
276	    state.board = emptyBoard();
277	    state.score = 0;
278	    state.level = 1;
279	    state.lines = 0;
280	    state.status = "running";
281	    state.next = Array.isArray(queue) ? queue.slice() : [];
282	    spawn();
283	    restartTimer();
284	    render();
285	  }
286	
287	  // ---- rendering (synchronous) ----
288	
289	  var boardEl = document.getElementById("board");
290	  var previewEl = document.getElementById("preview");
291	  var scoreEl = document.getElementById("score");
292	  var levelEl = document.getElementById("level");
293	  var linesEl = document.getElementById("lines");
294	  var gameOverEl = document.getElementById("game-over");
295	  var cellEls = [];
296	
297	  (function buildDom() {
298	    for (var r = 0; r < ROWS; r++) {
299	      var row = [];
300	      for (var c = 0; c < COLS; c++) {
301	        var el = document.createElement("div");
302	        el.className = "cell";
303	        el.setAttribute("data-testid", "cell");
304	        el.setAttribute("data-row", String(r));
305	        el.setAttribute("data-col", String(c));
306	        el.setAttribute("data-filled", "false");
307	        el.setAttribute("data-piece", "");
308	        boardEl.appendChild(el);
309	        row.push(el);
310	      }
311	      cellEls.push(row);
312	    }
313	  })();
314	
315	  // One preview item per upcoming piece, soonest first, drawn in its board colour.
316	  function previewItem(type) {
317	    var item = document.createElement("div");
318	    item.className = "preview";
319	    item.setAttribute("data-testid", "next-piece-item");
320	    item.setAttribute("data-piece", type);
321	    var cells = [];
322	    for (var i = 0; i < 8; i++) cells.push(item.appendChild(document.createElement("div")));
323	    SHAPES[type].forEach(function (o) { paint(cells[o[0] * 4 + o[1]], type); });
324	    return item;
325	  }
326	
327	  function paint(el, type) {
328	    el.className = el.className.replace(/\s*p-[A-Z]/g, "") + (type ? " p-" + type : "");
329	  }
330	
331	  function render() {
332	    var view = state.board.map(function (row) { return row.slice(); });
333	    if (state.current) {
334	      cellsOf(state.current).forEach(function (p) {
335	        if (p[0] >= 0 && p[0] < ROWS && p[1] >= 0 && p[1] < COLS) view[p[0]][p[1]] = state.current.type;
336	      });
337	    }
338	    for (var r = 0; r < ROWS; r++) {
339	      for (var c = 0; c < COLS; c++) {
340	        var el = cellEls[r][c], t = view[r][c];
341	        el.setAttribute("data-filled", t ? "true" : "false");
342	        el.setAttribute("data-piece", t);
343	        paint(el, t);
344	      }
345	    }
346	    previewEl.textContent = "";
347	    state.next.slice(0, PREVIEW_COUNT).forEach(function (type) {
348	      if (SHAPES[type]) previewEl.appendChild(previewItem(type));
349	    });
350	    gameOverEl.hidden = state.status !== "gameover";
351	    scoreEl.textContent = String(state.score);
352	    levelEl.textContent = String(state.level);
353	    linesEl.textContent = String(state.lines);
354	  }
355	
356	  // ---- timer ----
357	
358	  var timer = null;
359	  function onTimer() { gravityStep(); render(); }
360	  function restartTimer() {
361	    if (timer) clearInterval(timer);
362	    timer = setInterval(onTimer, GRAVITY_MS);
363	  }
364	
365	  // ---- input ----
366	
367	  var KEYS = { ArrowLeft: "left", ArrowRight: "right", ArrowDown: "softDrop", ArrowUp: "rotateCW", " ": "hardDrop" };
368	  document.addEventListener("keydown", function (e) {
369	    var action = KEYS[e.key];
370	    if (!action) return;
371	    e.preventDefault();
372	    doAction(action);
373	  });
374	  document.getElementById("restart").addEventListener("click", function (e) {
375	    e.currentTarget.blur();
376	    newGame();
377	  });
378	
379	  // ---- test control surface ----
380	
381	  window.__tetris = {
382	    newGame: function (queue) { newGame(queue); },
383	    setQueue: function (queue) {
384	      state.next = Array.isArray(queue) ? queue.slice() : [];
385	      render();
386	    },
387	    setBoard: function (rows) {
388	      state.board = rows.map(function (line) {
389	        return line.split("").map(function (ch) { return ch === "." ? "" : ch; });
390	      });
391	      render();
392	    },
393	    tick: function (n) {
394	      var steps = n === undefined ? 1 : n;
395	      for (var i = 0; i < steps; i++) gravityStep();
396	      render();
397	    },
398	    input: function (action) { doAction(action); },
399	    getBoard: function () {
400	      return state.board.map(function (row) {
401	        return row.map(function (t) { return t || "."; }).join("");
402	      });
403	    },
404	    getState: function () {
405	      return {
406	        current: state.current
407	          ? { type: state.current.type, cells: cellsOf(state.current) }
408	          : null,
409	        next: state.next.slice(),
410	        score: state.score,
411	        level: state.level,
412	        lines: state.lines,
413	        status: state.status
414	      };
415	    }
416	  };
417	
418	  newGame();
419	})();
420	</script>
421	</body>
422	</html>
